function LazyChart({children,className=''}){const ref=useRef(null);const [visible,setVisible]=useState(false);useEffect(()=>{if(!ref.current)return;const observer=new IntersectionObserver(([entry])=>{if(entry.isIntersecting){setVisible(true);observer.disconnect()}},{rootMargin:'180px'});observer.observe(ref.current);return()=>observer.disconnect()},[]);return <div ref={ref} className={className}>{visible?children:<div className="chart-placeholder" aria-label="Chart loads when approached"/>}</div>}

function ParticleField(){const ref=useRef(null);useEffect(()=>{const c=ref.current,ctx=c?.getContext('2d');if(!ctx)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let w=0,h=0,id=0;const pts=Array.from({length:34},(_,i)=>({x:(i*73%997)/997,y:(i*137%991)/991,vx:((i%5)-2)*.00007,vy:((i%7)-3)*.00005}));const resize=()=>{const r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,1.5);w=r.width;h=r.height;c.width=w*d;c.height=h*d;ctx.setTransform(d,0,0,d,0,0)};const draw=()=>{if(document.hidden)return;ctx.clearRect(0,0,w,h);pts.forEach((p,i)=>{if(!reduced){p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>1)p.vx*=-1;if(p.y<0||p.y>1)p.vy*=-1}const x=p.x*w,y=p.y*h;ctx.fillStyle='rgba(190,202,148,.7)';ctx.fillRect(x,y,2,2);for(let j=i+1;j<pts.length;j++){const q=pts[j],dx=(p.x-q.x)*w,dy=(p.y-q.y)*h;if(Math.hypot(dx,dy)<100){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(q.x*w,q.y*h);ctx.strokeStyle='rgba(190,202,148,.12)';ctx.stroke()}}});if(!reduced)id=requestAnimationFrame(draw)};resize();draw();if(!reduced)id=requestAnimationFrame(draw);addEventListener('resize',resize);return()=>{cancelAnimationFrame(id);removeEventListener('resize',resize)}},[]);return <canvas className="particle-field" aria-hidden="true" ref={ref}/>}
function ParticleInsights({points=[]}){
 const [selected,setSelected]=useState(null);const sorted=[...points].sort((a,b)=>b.churn_rate-a.churn_rate);const active=selected||sorted[0];const left=205,plotWidth=470,scaleMax=50;
 return <div className="particle-insights"><div className="particle-insights-head"><div><span className="eyebrow">INTERACTIVE VIEW / CUSTOMER MIX</span><h3>Observed churn by contract</h3><p>Share of customers in each contract group who churned in the sample.</p></div><span className="particle-hint">Hover, click, or focus a bar for details</span></div><svg viewBox="0 0 900 320" role="img" aria-label="Horizontal bar chart of observed churn percentages by contract type, on a zero to fifty percent scale"><text className="particle-axis-title" x="205" y="22">OBSERVED CHURN RATE</text>{[0,10,20,30,40,50].map(tick=>{const x=left+plotWidth*tick/scaleMax;return <g key={tick}><line className="particle-gridline" x1={x} y1="42" x2={x} y2="266"/><text className="particle-tick" x={x} y="39" textAnchor="middle">{tick}%</text></g>})}{sorted.map((point,index)=>{const y=91+index*68,width=plotWidth*Math.min(scaleMax,Math.max(0,point.churn_rate*100))/scaleMax;return <g key={point.Contract} className="particle-contract" role="button" tabIndex="0" aria-label={point.Contract+': '+(point.churn_rate*100).toFixed(1)+' percent observed churn, '+point.customers.toLocaleString()+' customers'} onMouseEnter={()=>setSelected(point)} onFocus={()=>setSelected(point)} onClick={()=>setSelected(point)}><text className="particle-contract-name" x="10" y={y+5}>{point.Contract}</text><rect className="particle-bar-track" x={left} y={y-13} width={plotWidth} height="26" rx="3"/><rect className="particle-bar" x={left} y={y-13} width={width} height="26" rx="3"/><g className="particle-dots">{Array.from({length:Math.max(2,Math.floor(width/22))},(_,i)=><circle key={i} cx={left+Math.min(width-5,8+i*22)} cy={y} r="1.5" style={{animationDelay:(i*.08)+'s'}}/>)}</g><text className="particle-rate" x="700" y={y+5}>{(point.churn_rate*100).toFixed(1)}%</text><text className="particle-volume" x="770" y={y+5}>{point.customers.toLocaleString()} customers</text></g>})}</svg><div className="particle-readout"><strong>{active?.Contract||'Waiting for analytics data'}</strong><span>{active?(active.churn_rate*100).toFixed(1)+'% observed churn':'—'}</span><span>{active?active.customers.toLocaleString()+' customers in group':'—'}</span><span>{active?'Mean model score '+(active.mean_probability*100).toFixed(1)+'%':'Hover over a bar to inspect it'}</span></div><p className="particle-caption">Bars use a 0–50% scale. Counts show the contract group size. Mean model score is a separate estimate; observed churn is historical, not a customer-specific prediction.</p></div>
}
