 const [customerQuery,setCustomerQuery]=useState(''),[riskFilter,setRiskFilter]=useState(''),[customerForm,setCustomerForm]=useState(customerDefaults),[prediction,setPrediction]=useState(null),[predictionBusy,setPredictionBusy]=useState(false),[predictionActions,setPredictionActions]=useState(null),[recommendationBusy,setRecommendationBusy]=useState(false),[predictionError,setPredictionError]=useState(''),[modelInfo,setModelInfo]=useState(null);
 const [sortOrder,setSortOrder]=useState('desc'),[customerOffset,setCustomerOffset]=useState(0),[helpOpen,setHelpOpen]=useState(false),[explanation,setExplanation]=useState(null),[explainBusy,setExplainBusy]=useState(false),[explainError,setExplainError]=useState(''),[bulkFile,setBulkFile]=useState(null),[bulkResult,setBulkResult]=useState(null),[bulkError,setBulkError]=useState(''),[bulkBusy,setBulkBusy]=useState(false);
