  const [highRiskThreshold,setHighRiskThreshold]=useState(.65),[saveRate,setSaveRate]=useState(.25),[campaignCost,setCampaignCost]=useState(20),[monitoring,setMonitoring]=useState(null),[monitoringBusy,setMonitoringBusy]=useState(false);
  const [outcomeFile,setOutcomeFile]=useState(null),[outcomeBusy,setOutcomeBusy]=useState(false),[outcomeMessage,setOutcomeMessage]=useState('');
  const [evaluationFile,setEvaluationFile]=useState(null),[evaluationBusy,setEvaluationBusy]=useState(false),[externalEvaluation,setExternalEvaluation]=useState(null),[evaluationError,setEvaluationError]=useState('');
 const refresh=async(offset=customerOffset,threshold=highRiskThreshold)=>{
  try { const params=new URLSearchParams({limit:'50',offset:String(offset),q:customerQuery,sort:sortOrder,high_risk_threshold:String(threshold)});if(riskFilter)params.set('risk',riskFilter);const [overview,customerList]=await Promise.all([fetch(`${API}/overview?high_risk_threshold=${threshold}`),fetch(`${API}/customers?${params}`)]); if(!overview.ok)throw Error(); const d=await overview.json(), c=customerList.ok?await customerList.json():{items:[]}; setData({...d,customers:c.items||[],customerTotal:c.total||0}); setError(''); }
  catch { setError('API offline · start the backend to load customer data'); }
 };
 const loadedSections=useRef(new Set());
 useEffect(()=>{refresh(0)},[]);
 useEffect(()=>{if(!['01','08'].includes(active)||loadedSections.current.has(active))return;loadedSections.current.add(active);const routes=active==='01'?['analytics','segments']:['model','monitoring'];if(active==='08')setMonitoringBusy(true);Promise.all(routes.map(x=>fetch(API+'/'+x+(x==='monitoring'?'?high_risk_threshold='+highRiskThreshold:'')).then(r=>r.ok?r.json():null))).then(values=>{if(active==='01'){setAnalytics(values[0]);setSegments(values[1])}else{setModelInfo(values[0]);setMonitoring(values[1])}}).catch(()=>{}).finally(()=>{if(active==='08')setMonitoringBusy(false)})},[active]);
 useEffect(()=>{setCustomerOffset(0)},[customerQuery,riskFilter,sortOrder]);
