 useEffect(()=>{const timer=setTimeout(()=>{fetch(`${API}/customers?${new URLSearchParams({limit:'50',offset:String(customerOffset),q:customerQuery,sort:sortOrder,high_risk_threshold:String(highRiskThreshold),...(riskFilter?{risk:riskFilter}:{})})}`).then(r=>r.ok?r.json():null).then(c=>{if(c)setData(d=>({...d,customers:c.items||[],customerTotal:c.total||0}))}).catch(()=>{})},250);return()=>clearTimeout(timer)},[customerQuery,riskFilter,sortOrder,customerOffset,highRiskThreshold]);
 const train=async()=>{const started=performance.now();setBusy(true);try{const r=await fetch(`${API}/model/train`,{method:'POST'});const result=await r.json();if(!r.ok)throw Error(result.detail||'Training failed');loadedSections.current.clear();await refresh(); const [a,s,model]=await Promise.all([fetch(`${API}/analytics`),fetch(`${API}/segments`),fetch(`${API}/model`)]);if(a.ok)setAnalytics(await a.json());if(s.ok)setSegments(await s.json());if(model.ok)setModelInfo(await model.json());}catch(e){setError(e.message||'Training could not start. Check backend and dataset setup.')}finally{await showLoadingFeedback(started);setBusy(false)}};
 const showRetention=async customer=>{const started=performance.now();setSelected(customer);setRetention(null);setLoadingDetail(true);try{const r=await fetch(`${API}/retention/${encodeURIComponent(customer.customer_id)}?high_risk_threshold=${highRiskThreshold}`);if(!r.ok)throw Error();setRetention(await r.json())}catch{setRetention({error:'Could not load this customer’s retention recommendations.'})}finally{await showLoadingFeedback(started);setLoadingDetail(false)}};
 const submitPrediction=async e=>{e.preventDefault();const started=performance.now();setPredictionBusy(true);setPrediction(null);setPredictionActions(null);setPredictionError('');const payload={...customerForm,SeniorCitizen:Number(customerForm.SeniorCitizen),tenure:Number(customerForm.tenure),MonthlyCharges:Number(customerForm.MonthlyCharges),TotalCharges:Number(customerForm.TotalCharges)};try{const r=await fetch(`${API}/predict?high_risk_threshold=${highRiskThreshold}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await r.json();if(!r.ok)throw Error(body.detail||'Prediction failed');setPrediction(body);setRecommendationBusy(true);try{const recommendation=await fetch(`${API}/retention/recommendations?high_risk_threshold=${highRiskThreshold}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const actions=await recommendation.json();if(recommendation.ok)setPredictionActions(actions)}catch{}finally{setRecommendationBusy(false)}}catch(err){setPredictionError(err.message);setRecommendationBusy(false)}finally{await showLoadingFeedback(started);setPredictionBusy(false)}};
 const formPayload=()=>({...customerForm,SeniorCitizen:Number(customerForm.SeniorCitizen),tenure:Number(customerForm.tenure),MonthlyCharges:Number(customerForm.MonthlyCharges),TotalCharges:Number(customerForm.TotalCharges)});
 const explainPrediction=async()=>{const started=performance.now();setExplainBusy(true);setExplanation(null);setExplainError('');try{const r=await fetch(`${API}/explain`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(formPayload())});const body=await r.json();if(!r.ok)throw Error(body.detail||'Explanation is unavailable');setExplanation(body)}catch(err){setExplainError(err.message)}finally{await showLoadingFeedback(started);setExplainBusy(false)}};
 const submitBulk=async e=>{e.preventDefault();if(!bulkFile)return;const started=performance.now();setBulkBusy(true);setBulkError('');setBulkResult(null);try{const form=new FormData();form.append('file',bulkFile);const r=await fetch(`${API}/predict/bulk?high_risk_threshold=${highRiskThreshold}`,{method:'POST',body:form});const body=await r.json();if(!r.ok)throw Error(body.detail||'Bulk scoring failed');setBulkResult(body)}catch(err){setBulkError(err.message)}finally{await showLoadingFeedback(started);setBulkBusy(false)}};
  const submitOutcomeLabels=async e=>{e.preventDefault();if(!outcomeFile)return;setOutcomeBusy(true);setOutcomeMessage('');try{const form=new FormData();form.append('file',outcomeFile);const r=await fetch(`${API}/monitoring/labels`,{method:'POST',body:form});const body=await r.json();if(!r.ok)throw Error(body.detail||'Could not attach outcome labels');setOutcomeMessage(`${body.updated} outcome${body.updated===1?'':'s'} attached to prior predictions.`);setOutcomeFile(null);await loadMonitoring()}catch(err){setOutcomeMessage(err.message)}finally{setOutcomeBusy(false)}};
