 const saveCsv=(rows,name)=>{const columns=['customer_id','prediction_event_id','churn_probability','probability_calibrated','risk','actual_churn'];const quote=value=>`"${String(value??'').replaceAll('\"','\"\"')}"`;const csv=[columns.join(','),...rows.map(row=>columns.map(key=>quote(row[key])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
