 const askInsight=async topic=>{const started=performance.now();setCopilotBusy(true);setCopilotAnswer('');try{if(topic==='risk'){const r=await fetch(`${API}/customers?limit=5&risk=HIGH&sort=desc&high_risk_threshold=${highRiskThreshold}`);if(!r.ok)throw Error('Customer risk data is unavailable');const d=await r.json();setCopilotAnswer(d.items.length?`There are ${d.total.toLocaleString()} customers in the high-risk group. Highest scores: ${d.items.map(c=>`${c.customer_id} (${(c.probability*100).toFixed(1)}%)`).join(', ')}.`:'There are no high-risk customers in the current scored dataset.')}else if(topic==='contract'){const r=await fetch(`${API}/analytics`);if(!r.ok)throw Error('Contract analytics are unavailable');const d=await r.json(),worst=[...d.contract].sort((a,b)=>b.churn_rate-a.churn_rate)[0];setCopilotAnswer(`${worst.Contract} has the highest observed churn rate at ${(worst.churn_rate*100).toFixed(1)}% across ${worst.customers.toLocaleString()} customers in this dataset.`)}else{const r=await fetch(`${API}/overview?high_risk_threshold=${highRiskThreshold}`);if(!r.ok)throw Error('Overview metrics are unavailable');const d=await r.json();setCopilotAnswer(`${d.metrics.churned_customers.toLocaleString()} customers churned and ${d.metrics.retained_customers.toLocaleString()} were retained. Overall observed churn rate is ${(d.metrics.churn_rate*100).toFixed(1)}%.`)}}catch(err){setCopilotAnswer(err.message)}finally{await showLoadingFeedback(started);setCopilotBusy(false)}};
 const m=data.metrics||{};
 const formatChargeBand=value=>{const match=String(value).match(/([0-9.]+),\s*([0-9.]+)/);return match?'$'+Math.round(Number(match[1]))+'–$'+Math.round(Number(match[2])):value};
 const chart=(title,key,items,field='churn_rate')=><div className="mini-chart"><div className="mini-chart-title"><span className="eyebrow">{title}</span><h3>{key==='charge_band'?'Churn rate by monthly charge range':key==='tenure_band'?'Churn rate by tenure':'Churn rate by payment method'}</h3><p>Bar height is the share of customers in each group who churned. Hover over a bar for the rate and group size.</p></div>{items?.length?<LazyChart className="mini-chart-body"><ResponsiveContainer width="100%" height={250}><BarChart data={items} margin={{top:12,right:12,bottom:20,left:8}}><CartesianGrid stroke="#ffffff12" vertical={false}/><XAxis dataKey={key} stroke="#999" tickLine={false} axisLine={false} tick={{fontSize:10}} interval={0} tickFormatter={v=>key==='charge_band'?formatChargeBand(v):String(v)}/><YAxis stroke="#999" tickLine={false} axisLine={false} tick={{fontSize:10}} tickFormatter={v=>Math.round(v*100)+'%'} domain={[0,'auto']}/><Tooltip content={({active,payload,label})=>active&&payload?.length?<div className="custom-chart-tooltip"><b>{key==='charge_band'?formatChargeBand(label):String(label)}</b><span>Observed churn: {(Number(payload[0].value)*100).toFixed(1)}%</span><span>{Number(payload[0].payload.customers||0).toLocaleString()} customers in group</span></div>:null}/><Bar dataKey={field} name="Observed churn rate" fill="#d9f36a" maxBarSize={42} radius={[3,3,0,0]}/></BarChart></ResponsiveContainer></LazyChart>:<p className="muted">This breakdown is unavailable until analytics data loads.</p>}</div>;
 const sampledClusters=useMemo(()=>{const byCluster=new Map();for(const point of segments?.clusters||[]){if(!byCluster.has(point.cluster))byCluster.set(point.cluster,[]);byCluster.get(point.cluster).push(point)}for(const [key,points] of byCluster){const stride=Math.max(1,Math.ceil(points.length/180));byCluster.set(key,points.filter((_,index)=>index%stride===0))}return byCluster},[segments]);
